using System.Windows; using System.Windows.Controls; namespace CloudClient; public sealed class ShareDialog:Window { readonly ComboBox targets=new(); readonly CheckBox write=new(){Content="Lesen & Schreiben erlauben"}; public ShareTarget? SelectedTarget=>targets.SelectedItem as ShareTarget; public bool CanWrite=>write.IsChecked==true; public ShareDialog(IEnumerable<ShareTarget> items){Title="Freigeben";Width=460;Height=285;WindowStartupLocation=WindowStartupLocation.CenterOwner;ResizeMode=ResizeMode.NoResize;var p=new StackPanel{Margin=new Thickness(28)};p.Children.Add(new TextBlock{Text="Für Benutzer oder Gruppe freigeben",FontSize=21,FontWeight=FontWeights.Bold,Margin=new Thickness(0,0,0,8)});p.Children.Add(new TextBlock{Text="Ziel auswählen und Zugriffsrecht festlegen.",Margin=new Thickness(0,0,0,16)});targets.ItemsSource=items;targets.SelectedIndex=0;targets.Height=36;p.Children.Add(targets);write.Margin=new Thickness(0,18,0,18);p.Children.Add(write);var b=new Button{Content="Freigeben",Height=38};b.Click+=(_,__)=>{if(SelectedTarget!=null)DialogResult=true;};p.Children.Add(b);Content=p;} public sealed class ShareTarget{public string Id{get;set;}="";public string Name{get;set;}="";public bool IsGroup{get;set;}public override string ToString()=>(IsGroup?"Gruppe: ":"Benutzer: ")+Name;} }